// Live GitHub stats for project cards (dynamic-first).
// Cards are rendered structure-only at build time; this fetches real
// stars/forks/language from api.github.com (one request per owner), fills
// the hidden slots and re-sorts the grid by live star count.
// On API failure (rate limit, offline) it falls back to the committed
// snapshot at /data/github.json (regenerated by scripts/bake_data.py).
// Results are cached in sessionStorage for 10 minutes to stay under rate limits.
(function () {
  "use strict";
  var grid = document.querySelector("[data-gh-grid]");
  if (!grid) return;
  var cards = Array.prototype.slice.call(grid.querySelectorAll("[data-gh-card]"));
  cards = cards.filter(function (c) { return c.dataset.owner && c.dataset.repo; });
  if (!cards.length) return;

  var langs = {};
  try { langs = JSON.parse(grid.getAttribute("data-langs") || "{}"); } catch (e) {}

  var CACHE_KEY = "rk-gi...e";
  var CACHE_TTL = 600000; // 10 minutes

  function readCache() {
    try {
      var c = JSON.parse(sessionStorage.getItem(CACHE_KEY));
      if (c && c.map && Date.now() - c.t < CACHE_TTL) return c.map;
    } catch (e) {}
    return null;
  }

  function writeCache(map) {
    try { sessionStorage.setItem(CACHE_KEY, JSON.stringify({ t: Date.now(), map: map })); } catch (e) {}
  }

  function gh(url) {
    return fetch(url, { headers: { Accept: "application/vnd.github+json" } }).then(function (r) {
      if (!r.ok) throw new Error("github api " + r.status);
      return r.json();
    });
  }

  function entry(r) {
    return { stars: r.stargazers_count, forks: r.forks_count, language: r.language };
  }

  function keyOf(owner, repo) { return (owner + "/" + repo).toLowerCase(); }

  function setStat(card, sel, numSel, value, min, unit) {
    var el = card.querySelector(sel);
    if (!el) return;
    if (typeof value === "number" && value >= min) {
      el.hidden = false;
      el.querySelector(numSel).textContent = String(value);
      el.title = String(value) + " " + unit;
    } else {
      el.hidden = true;
    }
  }

  function apply(map) {
    cards.forEach(function (card) {
      var e = map[keyOf(card.dataset.owner, card.dataset.repo)] ||
              map[card.dataset.repo.toLowerCase()];
      if (!e) return;
      setStat(card, ".rk-card-stars", ".rk-card-stars-n", e.stars, 10, "stars");
      setStat(card, ".rk-card-forks", ".rk-card-forks-n", e.forks, 1, "forks");
      var langEl = card.querySelector(".rk-card-lang");
      if (langEl) {
        if (e.language) {
          langEl.hidden = false;
          langEl.querySelector(".rk-card-lang-name").textContent = e.language;
          langEl.querySelector(".rk-lang-dot").style.background =
            langs[e.language] || "#8b5cf6";
        } else {
          langEl.hidden = true;
        }
      }
      card.dataset.stars = String(e.stars || 0);
    });
    // Re-sort by live stars desc, tie-break by repo name.
    cards.slice().sort(function (a, b) {
      var d = parseInt(b.dataset.stars || "0", 10) - parseInt(a.dataset.stars || "0", 10);
      if (d) return d;
      return String(a.dataset.repo).localeCompare(String(b.dataset.repo));
    }).forEach(function (c) { grid.appendChild(c); });
  }

  function fromOwnerRepos(list) {
    var map = {};
    (list || []).forEach(function (r) { map[keyOf(r.owner.login, r.name)] = entry(r); });
    return map;
  }

  function merge(dst, src) {
    Object.keys(src).forEach(function (k) { dst[k] = src[k]; });
    return dst;
  }

  function fallbackSnapshot() {
    return fetch("/data/github.json").then(function (r) {
      if (!r.ok) throw new Error("no snapshot");
      return r.json();
    }).then(function (snap) {
      var map = {};
      // Snapshot keys are bare lowercase repo names/slugs (see bake_data.py).
      Object.keys(snap).forEach(function (k) {
        var e = snap[k];
        map[k] = { stars: e.stars, forks: e.forks, language: e.language };
      });
      return map;
    });
  }

  function run() {
    var cached = readCache();
    if (cached) { apply(cached); return; }

    var owners = {};
    cards.forEach(function (c) { owners[c.dataset.owner.toLowerCase()] = 1; });

    Promise.all(Object.keys(owners).map(function (o) {
      return gh("https://api.github.com/users/" + encodeURIComponent(o) +
                "/repos?per_page=100&sort=pushed")
        .then(fromOwnerRepos)
        .catch(function () { return {}; });
    })).then(function (maps) {
      var map = {};
      maps.forEach(function (m) { merge(map, m); });

      // Cards missing from owner listings (renamed / org-hosted repos):
      // one targeted request each — the API follows renames and redirects.
      var missing = {};
      cards.forEach(function (c) {
        if (!map[keyOf(c.dataset.owner, c.dataset.repo)] && !map[c.dataset.repo.toLowerCase()]) {
          missing[keyOf(c.dataset.owner, c.dataset.repo)] = c;
        }
      });
      var singles = Object.keys(missing).slice(0, 8);
      return Promise.all(singles.map(function (k) {
        var c = missing[k];
        return gh("https://api.github.com/repos/" + c.dataset.owner + "/" + c.dataset.repo)
          .then(function (r) {
            var e = entry(r);
            map[k] = e;
            map[keyOf(r.owner.login, r.name)] = e;
          })
          .catch(function () {});
      })).then(function () { return map; });
    }).then(function (map) {
      writeCache(map);
      apply(map);
    }).catch(function () {
      return fallbackSnapshot().then(apply).catch(function () { /* keep cards plain */ });
    });
  }

  run();
})();
